// 후: 규칙이 타입 안으로 들어온다
class Money {
  private constructor(readonly amount: number, readonly currency: Currency) {}
  static won(v: number) {
    if (!Number.isInteger(v)) throw new Error('원 단위는 정수');
    return new Money(v, 'KRW');
  }
  plus(o: Money) { assertSame(this.currency, o.currency); return new Money(this.amount + o.amount, this.currency); }
}

class Order {
  cancel(now: Date) {
    if (this.status === 'shipped') throw new DomainError('배송 시작 후에는 취소할 수 없습니다');
    this.status = 'canceled';
  }
}
